static void Read_JedecId(uint8_t id[3])
{
  uint8_t tx[4] = {0x9F, 0, 0, 0};   /* 0x9F 读 JEDEC ID */
  uint8_t rx[4] = {0};

  HAL_GPIO_WritePin(GPIOA, GPIO_PIN_4, GPIO_PIN_RESET);  /* CS 低 */
