#define PARAM_ADDR  0x08060000UL      /* F4 Sector 7；按实际芯片调整 */

/* USER CODE BEGIN 4 */
static int SaveParam(uint32_t value)
{
  FLASH_EraseInitTypeDef erase = {0};
  uint32_t err = 0;

  HAL_FLASH_Unlock();
  __HAL_FLASH_CLEAR_FLAG(FLASH_FLAG_EOP | FLASH_FLAG_OPERR | FLASH_FLAG_WRPERR
                       | FLASH_FLAG_PGAERR | FLASH_FLAG_PGPERR | FLASH_FLAG_PGSERR);

  erase.TypeErase = FLASH_TYPEERASE_SECTORS;   /* F1 用 FLASH_TYPEERASE_PAGES */
  erase.Sector = FLASH_SECTOR_7;
  erase.NbSectors = 1;
  erase.VoltageRange = FLASH_VOLTAGE_RANGE_3;
  if (HAL_FLASHEx_Erase(&erase, &err) != HAL_OK) { HAL_FLASH_Lock(); return -1; }

  if (HAL_FLASH_Program(FLASH_TYPEPROGRAM_WORD, PARAM_ADDR, value) != HAL_OK) {
    HAL_FLASH_Lock();
    return -1;
  }
  HAL_FLASH_Lock();
  return (*(volatile uint32_t *)PARAM_ADDR == value) ? 0 : -1;
}
/* USER CODE END 4 */

